private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int index = i;
    while (index < bb.limit()) {
        int b = bb.get(index++);
        if (b < 0) {
            // Invalid octet
            throw new IllegalArgumentException("Invalid octet: " + b);
        }
        if (b < 0x80) {
            // ASCII character
            sb.append((char) b);
        } else if (b < 0xC0) {
            // Invalid octet
            throw new IllegalArgumentException("Invalid octet: " + b);
        } else if (b < 0xE0) {
            // Two-byte sequence
            int b2 = bb.get(index++);
            if (b2 < 0x80 || b2 > 0xBF) {
                // Invalid octet
                throw new IllegalArgumentException("Invalid octet: " + b2);
            }
            sb.append((char) ((b & 0x1F) << 6 | b2 & 0x3F));
        } else if (b < 0xF0) {
            // Three-byte sequence
            int b2 = bb.get(index++);
            int b3 = bb.get(index++);
            if (b2 < 0x80 || b2 > 0xBF || b3 < 0x80 || b3 > 0xBF) {
                // Invalid octet
                throw new IllegalArgumentException("Invalid octet: " + b2 + " or " + b3);
            }
            sb.append((char) ((b & 0x0F) << 12 | (b2 & 0x3F) << 6 | b3 & 0x3F));
        } else {
            // Four-byte sequence
            int b2 = bb.get(index++);
            int b3 = bb.get(index++);
            int b4 = bb.get(index++);
            if (b2 < 0x80 || b2 > 0xBF || b3 < 0x80 || b3 > 0xBF || b4 < 0x80 || b4 > 0xBF) {
                // Invalid octet
                throw new IllegalArgumentException("Invalid octet: " + b2 + " or " + b3 + " or " + b4);
            }
            sb.append((char) ((b & 0x07) << 18 | (b2 & 0x3F) << 12 | (b3 & 0x3F) << 6 | b4 & 0x3F));
        }
    }
    return index;
}
