/**
 * Parses the conversion pattern and extracts the format specifiers.
 *
 * @param conversionPattern the conversion pattern to parse
 * @return a list of format specifiers
 */
private List<String> parseConversionPattern(String conversionPattern) {
    // Step 1: Split the conversion pattern into a list of tokens
    List<String> tokens = Arrays.asList(conversionPattern.split("\\s+"));

    // Step 2: Filter the tokens to only include format specifiers
    List<String> formatSpecifiers = tokens.stream()
            .filter(token -> token.startsWith("%"))
            .collect(Collectors.toList());

    return formatSpecifiers;
}

/**
 * Replaces the format specifiers with the corresponding values from the event.
 *
 * @param event the logging event
 * @param formatSpecifiers the list of format specifiers
 * @return the formatted string
 */
private String replaceFormatSpecifiers(LoggingEvent event, List<String> formatSpecifiers) {
    // Step 1: Create a map of format specifiers and their corresponding values
    Map<String, String> formatSpecifierValues = new HashMap<>();
    for (String formatSpecifier : formatSpecifiers) {
        String value = event.getFormattedMessage(formatSpecifier);
        formatSpecifierValues.put(formatSpecifier, value);
    }

    // Step 2: Replace the format specifiers with their corresponding values
    String formattedString = event.getFormattedMessage();
    for (Map.Entry<String, String> entry : formatSpecifierValues.entrySet()) {
        String formatSpecifier = entry.getKey();
        String value = entry.getValue();
        formattedString = formattedString.replace(formatSpecifier, value);
    }

    return formattedString;
}

