public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {

    // Calculate the size of the message
    int size = schema.getSerializedSize(message, buffer);

    // Write the size of the message as a varint
    int varintSize = CodedOutputStream.computeRawVarint32Size(size);
    CodedOutputStream cos = CodedOutputStream.newInstance(out, varintSize);
    cos.writeRawVarint32(size);

    // Write the message
    schema.writeTo(message, cos);

    // Flush the buffer
    cos.flush();

    return size;
}

